const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lacRouge = ee.Geometry.Point([-74.43, 46.95]).buffer(2000);

  const date2024Start = '2024-06-15';
  const date2024End = '2024-06-28';
  const date2025Start = '2025-06-08';
  const date2025End = '2025-06-22';

  // 2. Cloud masking function
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBit = 1 << 10;
    const cirrusBit = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBit).eq(0)
        .and(qa.bitwiseAnd(cirrusBit).eq(0));
    return image.updateMask(mask);
  }

  // 3. Water detection function
  function addNDWI(image) {
    const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI');
    return image.addBands(ndwi);
  }

  // 4. Data Acquisition for 2024
  let col2024 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lacRouge)
    .filterDate(date2024Start, date2024End)
    .map(maskClouds)
    .map(addNDWI);

  const size2024 = await col2024.size().getInfo();
  console.log(`2024 Images found: ${size2024}`);

  if (size2024 === 0) {
    console.log("No data for June 2024.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 5. Data Acquisition for 2025
  let col2025 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lacRouge)
    .filterDate(date2025Start, date2025End)
    .map(maskClouds)
    .map(addNDWI);

  const size2025 = await col2025.size().getInfo();
  console.log(`2025 Images found: ${size2025}`);

  if (size2025 === 0) {
    console.log("No data for June 2025.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 6. Create composite images
  const img2024 = col2024.median();
  const img2025 = col2025.median();

  // 7. Detect water (NDWI > 0)
  const water2024 = img2024.select('NDWI').gt(0);
  const water2025 = img2025.select('NDWI').gt(0);

  // 8. Calculate water area
  const stats2024 = await water2024.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: lacRouge,
    scale: 30,
    maxPixels: 1e9
  }).getInfo();

  const waterPixels2024 = stats2024.NDWI_sum || 0;
  const totalPixels2024 = stats2024.NDWI_count || 0;

  console.log(`2024: Water pixels=${waterPixels2024}, Total=${totalPixels2024}`);

  if (totalPixels2024 === 0) {
    console.log("No valid pixels for 2024 after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  const stats2025 = await water2025.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: lacRouge,
    scale: 30,
    maxPixels: 1e9
  }).getInfo();

  const waterPixels2025 = stats2025.NDWI_sum || 0;
  const totalPixels2025 = stats2025.NDWI_count || 0;

  console.log(`2025: Water pixels=${waterPixels2025}, Total=${totalPixels2025}`);

  if (totalPixels2025 === 0) {
    console.log("No valid pixels for 2025 after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 9. Calculate shrinkage percentage
  if (waterPixels2024 === 0) {
    console.log("No water detected in 2024 baseline.");
    console.log("<answer>C3</answer>");
    return;
  }

  const shrinkagePercent = ((waterPixels2024 - waterPixels2025) / waterPixels2024) * 100;
  console.log(`Shrinkage: ${shrinkagePercent.toFixed(2)}%`);

  // 10. Final Answer
  if (shrinkagePercent > 90) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
